def skiaanimationthinking(thought, nextThoughtNeeded, thoughtNumber, totalThoughts, isRevision=None, revisesThought=None, branchFromThought=None, branchId=None, needsMoreThoughts=None, animationTechnique=None, performanceConsideration=None, codeSnippet=None, visualEffect=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0092000" if __import__("os").path.isdir("./environment_mix/0092000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    inv_file = "tool_invocations.json"
    sess_file = "thinking_sessions.json"
    th_file = "session_thoughts.json"
    link_file = "thought_links.json"

    # Validate required types
    if not isinstance(thought, str) or thought == "":
        return _err("VALIDATION_ERROR", "thought must be a non-empty string")
    if not isinstance(nextThoughtNeeded, bool):
        return _err("VALIDATION_ERROR", "nextThoughtNeeded must be a boolean")
    if not isinstance(thoughtNumber, int):
        return _err("VALIDATION_ERROR", "thoughtNumber must be an integer")
    if not isinstance(totalThoughts, int):
        return _err("VALIDATION_ERROR", "totalThoughts must be an integer")
    if thoughtNumber < 1:
        return _err("VALIDATION_ERROR", "thoughtNumber must be >= 1")
    if totalThoughts < 1:
        return _err("VALIDATION_ERROR", "totalThoughts must be >= 1")

    # Optional fields validation
    if isRevision is None:
        isRevision = False
    if not isinstance(isRevision, bool):
        return _err("VALIDATION_ERROR", "isRevision must be a boolean")
    if revisesThought is not None and (not isinstance(revisesThought, int) or revisesThought < 1):
        return _err("VALIDATION_ERROR", "revisesThought must be an integer >= 1 when provided")
    if branchFromThought is not None and (not isinstance(branchFromThought, int) or branchFromThought < 1):
        return _err("VALIDATION_ERROR", "branchFromThought must be an integer >= 1 when provided")
    if branchId is not None and not isinstance(branchId, str):
        return _err("VALIDATION_ERROR", "branchId must be a string when provided")
    if needsMoreThoughts is not None and not isinstance(needsMoreThoughts, bool):
        return _err("VALIDATION_ERROR", "needsMoreThoughts must be a boolean when provided")
    for nm, val in [
        ("animationTechnique", animationTechnique),
        ("performanceConsideration", performanceConsideration),
        ("codeSnippet", codeSnippet),
        ("visualEffect", visualEffect),
    ]:
        if val is not None and not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{nm} must be a string when provided")

    # Constraint: nextThoughtNeeded=false implies needsMoreThoughts is null or false
    if nextThoughtNeeded is False and needsMoreThoughts is True:
        return _err("VALIDATION_ERROR", "When nextThoughtNeeded is false, needsMoreThoughts cannot be true")

    # Revision constraints
    if isRevision and revisesThought is None:
        return _err("VALIDATION_ERROR", "revisesThought must be provided when isRevision=true")
    if (not isRevision) and revisesThought is not None:
        return _err("VALIDATION_ERROR", "revisesThought must be omitted when isRevision=false")

    # Create invocation row immediately (will be updated later with status/thought_id/response if possible)
    invocations = _load(inv_file)
    inv_id = f"inv_{uuid.uuid4().hex}"
    request_payload = {
        "thought": thought,
        "nextThoughtNeeded": nextThoughtNeeded,
        "thoughtNumber": thoughtNumber,
        "totalThoughts": totalThoughts,
        "isRevision": isRevision,
        "revisesThought": revisesThought,
        "branchFromThought": branchFromThought,
        "branchId": branchId,
        "needsMoreThoughts": needsMoreThoughts,
        "animationTechnique": animationTechnique,
        "performanceConsideration": performanceConsideration,
        "codeSnippet": codeSnippet,
        "visualEffect": visualEffect,
    }
    inv_row = {
        "id": inv_id,
        "tool_name": "skiaanimationthinking",
        "session_id": None,
        "thought_id": None,
        "request_payload": request_payload,
        "response_payload": None,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv_row)
    _save(inv_file, invocations)

    def _finalize_invocation(session_id, thought_id, response_payload):
        invocations2 = _load(inv_file)
        for r in invocations2:
            if r.get("id") == inv_id:
                r["session_id"] = session_id
                r["thought_id"] = thought_id
                r["response_payload"] = response_payload
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save(inv_file, invocations2)

    # Resolve/construct session (ambient auth: no credential parameter; pick/create viable session)
    sessions = _load(sess_file)

    # Infer provided session_id from extra params if caller supplied it (not in schema but common in tool stacks)
    session_id = None
    if isinstance(_extra, dict):
        sid = _extra.get("session_id") or _extra.get("sessionId")
        if sid is not None:
            if not isinstance(sid, str) or sid == "":
                response = _err("VALIDATION_ERROR", "session_id must be a non-empty string when provided")
                _finalize_invocation(None, None, response)
                return response
            session_id = sid

    sess = None
    if session_id:
        for s in sessions:
            if s.get("id") == session_id:
                sess = s
                break
        if sess is None:
            response = _err("NOT_FOUND", "Thinking session not found", id=session_id)
            _finalize_invocation(None, None, response)
            return response
    else:
        # Create new session
        session_id = f"ts_{uuid.uuid4().hex}"
        sess = {
            "id": session_id,
            "status": "active",
            "title": None,
            "context": None,
            "estimated_total_thoughts": int(totalThoughts),
            "last_thought_number": 0,
            "default_branch_id": "main",
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(sess)
        _save(sess_file, sessions)

    # Validate session lifecycle (cannot append to completed/abandoned)
    if sess.get("status") != "active":
        response = _err("INVALID_TRANSITION", "Cannot append thoughts to a non-active session", status=sess.get("status"))
        _finalize_invocation(session_id, None, response)
        return response

    # Determine branch_id (defaulting)
    effective_branch_id = branchId
    if effective_branch_id is None or (isinstance(effective_branch_id, str) and effective_branch_id.strip() == ""):
        effective_branch_id = sess.get("default_branch_id")
    if not isinstance(effective_branch_id, str) or effective_branch_id == "":
        response = _err("VALIDATION_ERROR", "branchId resolved to an empty value")
        _finalize_invocation(session_id, None, response)
        return response

    thoughts = _load(th_file)
    links = _load(link_file)

    # Helper: find thought by (session_id, branch_id, thought_number) where status != deleted
    def _find_existing_non_deleted(session_id_, branch_id_, thought_number_):
        for t in thoughts:
            if t.get("session_id") == session_id_ and t.get("branch_id") == branch_id_ and t.get("thought_number") == thought_number_ and t.get("status") != "deleted":
                return t
        return None

    # Reject duplicates (unique constraint where status <> deleted)
    if _find_existing_non_deleted(session_id, effective_branch_id, thoughtNumber) is not None:
        response = _err(
            "CONFLICT",
            "A non-deleted thought with the same (session_id, branch_id, thought_number) already exists; use isRevision + revisesThought or a new branch instead.",
            session_id=session_id,
            branch_id=effective_branch_id,
            thought_number=thoughtNumber,
        )
        _finalize_invocation(session_id, None, response)
        return response

    # Validate referenced thoughts exist in same session (and not deleted)
    def _find_thought_in_session_by_number(session_id_, thought_number_):
        # Thought numbers are per-branch in uniqueness, but references in business rules are "within same session".
        # We'll resolve to the most recently updated non-deleted thought with that thought_number in any branch.
        candidates = [t for t in thoughts if t.get("session_id") == session_id_ and t.get("thought_number") == thought_number_ and t.get("status") != "deleted"]
        if not candidates:
            return None
        def _ts(v):
            try:
                return v.get("updated_at") or v.get("created_at") or ""
            except Exception:
                return ""
        candidates.sort(key=_ts, reverse=True)
        return candidates[0]

    revised_target = None
    branch_from_target = None
    if isRevision:
        revised_target = _find_thought_in_session_by_number(session_id, revisesThought)
        if revised_target is None:
            response = _err("NOT_FOUND", "Referenced revisesThought does not exist in this session", session_id=session_id, revisesThought=revisesThought)
            _finalize_invocation(session_id, None, response)
            return response

    if branchFromThought is not None:
        branch_from_target = _find_thought_in_session_by_number(session_id, branchFromThought)
        if branch_from_target is None:
            response = _err("NOT_FOUND", "Referenced branchFromThought does not exist in this session", session_id=session_id, branchFromThought=branchFromThought)
            _finalize_invocation(session_id, None, response)
            return response

    # Create thought row
    thought_id = f"th_{uuid.uuid4().hex}"
    thought_row = {
        "id": thought_id,
        "session_id": session_id,
        "status": "recorded",
        "thought_number": int(thoughtNumber),
        "total_thoughts": int(totalThoughts),
        "thought": thought,
        "next_thought_needed": bool(nextThoughtNeeded),
        "needs_more_thoughts": needsMoreThoughts if needsMoreThoughts is not None else None,
        "is_revision": bool(isRevision),
        "revises_thought_number": int(revisesThought) if revisesThought is not None else None,
        "branch_from_thought_number": int(branchFromThought) if branchFromThought is not None else None,
        "branch_id": effective_branch_id,
        "animation_technique": animationTechnique,
        "performance_consideration": performanceConsideration,
        "code_snippet": codeSnippet,
        "visual_effect": visualEffect,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce schema constraints for revision flags
    if thought_row["is_revision"] is False and thought_row["revises_thought_number"] is not None:
        response = _err("VALIDATION_ERROR", "isRevision=false implies revisesThought must be null")
        _finalize_invocation(session_id, None, response)
        return response
    if thought_row["is_revision"] is True and thought_row["revises_thought_number"] is None:
        response = _err("VALIDATION_ERROR", "isRevision=true implies revisesThought must be provided")
        _finalize_invocation(session_id, None, response)
        return response

    # Persist thought
    thoughts.append(thought_row)
    _save(th_file, thoughts)

    created_links = []

    # Create revises link + mark revised thought superseded (unless deleted)
    if isRevision and revised_target is not None:
        # unique(from_thought_id, link_type) and unique(from,to,link_type)
        for l in links:
            if l.get("from_thought_id") == thought_id and l.get("link_type") == "revises":
                response = _err("CONFLICT", "Revises link already exists for this thought")
                _finalize_invocation(session_id, thought_id, response)
                return response

        link_id = f"lnk_{uuid.uuid4().hex}"
        link_row = {
            "id": link_id,
            "session_id": session_id,
            "from_thought_id": thought_id,
            "to_thought_id": revised_target.get("id"),
            "link_type": "revises",
            "created_at": now,
            "updated_at": now,
        }
        if link_row["from_thought_id"] == link_row["to_thought_id"]:
            response = _err("VALIDATION_ERROR", "from_thought_id cannot equal to_thought_id")
            _finalize_invocation(session_id, thought_id, response)
            return response

        # Uniqueness checks
        for l in links:
            if l.get("from_thought_id") == link_row["from_thought_id"] and l.get("link_type") == link_row["link_type"]:
                response = _err("CONFLICT", "A link of this type from the thought already exists")
                _finalize_invocation(session_id, thought_id, response)
                return response
            if l.get("from_thought_id") == link_row["from_thought_id"] and l.get("to_thought_id") == link_row["to_thought_id"] and l.get("link_type") == link_row["link_type"]:
                response = _err("CONFLICT", "This link already exists")
                _finalize_invocation(session_id, thought_id, response)
                return response

        links.append(link_row)
        _save(link_file, links)
        created_links.append(link_row)

        # Mark revised thought as superseded if recorded; keep deleted as-is
        thoughts2 = _load(th_file)
        for t in thoughts2:
            if t.get("id") == revised_target.get("id"):
                if t.get("status") == "recorded":
                    t["status"] = "superseded"
                    t["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save(th_file, thoughts2)

    # Create branches_from link if requested
    if branch_from_target is not None:
        for l in links:
            if l.get("from_thought_id") == thought_id and l.get("link_type") == "branches_from":
                response = _err("CONFLICT", "branches_from link already exists for this thought")
                _finalize_invocation(session_id, thought_id, response)
                return response

        link_id = f"lnk_{uuid.uuid4().hex}"
        link_row = {
            "id": link_id,
            "session_id": session_id,
            "from_thought_id": thought_id,
            "to_thought_id": branch_from_target.get("id"),
            "link_type": "branches_from",
            "created_at": now,
            "updated_at": now,
        }
        if link_row["from_thought_id"] == link_row["to_thought_id"]:
            response = _err("VALIDATION_ERROR", "from_thought_id cannot equal to_thought_id")
            _finalize_invocation(session_id, thought_id, response)
            return response

        # Uniqueness checks
        for l in links:
            if l.get("from_thought_id") == link_row["from_thought_id"] and l.get("link_type") == link_row["link_type"]:
                response = _err("CONFLICT", "A link of this type from the thought already exists")
                _finalize_invocation(session_id, thought_id, response)
                return response
            if l.get("from_thought_id") == link_row["from_thought_id"] and l.get("to_thought_id") == link_row["to_thought_id"] and l.get("link_type") == link_row["link_type"]:
                response = _err("CONFLICT", "This link already exists")
                _finalize_invocation(session_id, thought_id, response)
                return response

        links.append(link_row)
        _save(link_file, links)
        created_links.append(link_row)

    # Update session aggregates
    sessions2 = _load(sess_file)
    for s in sessions2:
        if s.get("id") == session_id:
            # estimated_total_thoughts = max(existing, request.totalThoughts)
            try:
                existing_est = int(s.get("estimated_total_thoughts", 1))
            except Exception:
                existing_est = 1
            try:
                existing_last = int(s.get("last_thought_number", 0))
            except Exception:
                existing_last = 0
            s["estimated_total_thoughts"] = max(existing_est, int(totalThoughts))
            s["last_thought_number"] = max(existing_last, int(thoughtNumber))
            s["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save(sess_file, sessions2)

    # Potentially complete session
    def _should_complete():
        # Only consider completion if this thought is on default branch and indicates no further thought.
        sessions3 = _load(sess_file)
        sess3 = None
        for s in sessions3:
            if s.get("id") == session_id:
                sess3 = s
                break
        if not sess3:
            return False, None

        default_branch = sess3.get("default_branch_id")
        if effective_branch_id != default_branch:
            return False, sess3

        # interpret "no more thoughts" when nextThoughtNeeded=false OR needsMoreThoughts=false when provided
        no_more = (nextThoughtNeeded is False) or (needsMoreThoughts is False)
        if not no_more:
            return False, sess3

        # "no other active branches in progress": if any branch != default has latest thought with next_thought_needed==True, keep active
        thoughts3 = _load(th_file)
        latest_by_branch = {}
        for t in thoughts3:
            if t.get("session_id") != session_id:
                continue
            if t.get("status") == "deleted":
                continue
            b = t.get("branch_id")
            if not b:
                continue
            tn = t.get("thought_number")
            if not isinstance(tn, int):
                continue
            cur = latest_by_branch.get(b)
            if cur is None or tn > cur.get("thought_number", -1):
                latest_by_branch[b] = t

        for b, t in latest_by_branch.items():
            if b == default_branch:
                continue
            if t.get("next_thought_needed") is True:
                return False, sess3

        return True, sess3

    complete, sess3 = _should_complete()
    if complete and sess3 and sess3.get("status") == "active":
        sessions4 = _load(sess_file)
        for s in sessions4:
            if s.get("id") == session_id:
                # active -> completed is allowed
                s["status"] = "completed"
                s["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save(sess_file, sessions4)

    # Build response
    response = {
        "session": _load(sess_file) and next((s for s in _load(sess_file) if s.get("id") == session_id), None),
        "thought": next((t for t in _load(th_file) if t.get("id") == thought_id), None),
        "links_created": created_links,
        "invocation": {"id": inv_id, "tool_name": "skiaanimationthinking"},
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

    _finalize_invocation(session_id, thought_id, response)
    return response

def listThinkingSessions(status=None, query=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0092000" if __import__("os").path.isdir("./environment_mix/0092000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    inv_file = "tool_invocations.json"
    sess_file = "thinking_sessions.json"

    # Validate filters
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "completed", "abandoned"):
            return _err("VALIDATION_ERROR", "status must be one of: active, completed, abandoned")
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Record invocation (read included)
    invocations = _load(inv_file)
    inv_id = f"inv_{uuid.uuid4().hex}"
    request_payload = {"status": status, "query": query, "limit": limit, "cursor": cursor}
    inv_row = {
        "id": inv_id,
        "tool_name": "skiaanimationthinking",
        "session_id": None,
        "thought_id": None,
        "request_payload": {"endpoint": "listThinkingSessions", **request_payload},
        "response_payload": None,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv_row)
    _save(inv_file, invocations)

    def _finalize(response_payload):
        inv2 = _load(inv_file)
        for r in inv2:
            if r.get("id") == inv_id:
                r["response_payload"] = response_payload
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save(inv_file, inv2)

    sessions = _load(sess_file)

    # Filter
    if status is not None:
        sessions = [s for s in sessions if s.get("status") == status]

    if query is not None and query.strip() != "":
        q = query.casefold()
        def _hay(s):
            t = s.get("title") or ""
            c = s.get("context") or ""
            return (t + "\n" + c).casefold()
        sessions = [s for s in sessions if q in _hay(s)]

    # Sort reverse chronological by created_at (fallback updated_at, id)
    def _k(s):
        return (s.get("created_at") or "", s.get("updated_at") or "", s.get("id") or "")
    sessions.sort(key=_k, reverse=True)

    # Cursor handling: opaque base64 of last seen created_at|id
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) != 2:
                resp = _err("VALIDATION_ERROR", "Invalid cursor")
                _finalize(resp)
                return resp
            c_created, c_id = parts
            # find index after that item in current filtered+sorted list
            idx = None
            for i, s in enumerate(sessions):
                if (s.get("created_at") or "") == c_created and (s.get("id") or "") == c_id:
                    idx = i
                    break
            if idx is None:
                resp = _err("VALIDATION_ERROR", "Cursor does not match current result set")
                _finalize(resp)
                return resp
            start = idx + 1
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            resp = _err("VALIDATION_ERROR", "Invalid cursor encoding")
            _finalize(resp)
            return resp

    page = sessions[start:start + limit]
    has_more = (start + limit) < len(sessions)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        token = f"{last.get('created_at') or ''}|{last.get('id') or ''}"
        next_cursor = base64.urlsafe_b64encode(token.encode("utf-8")).decode("utf-8")

    response = {
        "data": page,
        "meta": {
            "total": len(sessions),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        },
        "invocation": {"id": inv_id, "tool_name": "skiaanimationthinking"},
    }
    _finalize(response)
    return response

def updateThinkingSession(id, status=None, title=None, context=None, estimated_total_thoughts=None, default_branch_id=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0092000" if __import__("os").path.isdir("./environment_mix/0092000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(id, str) or id == "":
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # Validate inputs
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "completed", "abandoned"):
            return _err("VALIDATION_ERROR", "status must be one of: active, completed, abandoned")
    if title is not None and not isinstance(title, str):
        return _err("VALIDATION_ERROR", "title must be a string")
    if context is not None and not isinstance(context, str):
        return _err("VALIDATION_ERROR", "context must be a string")
    if estimated_total_thoughts is not None:
        if not isinstance(estimated_total_thoughts, int):
            return _err("VALIDATION_ERROR", "estimated_total_thoughts must be an integer")
        if estimated_total_thoughts < 1:
            return _err("VALIDATION_ERROR", "estimated_total_thoughts must be >= 1")
    if default_branch_id is not None:
        if not isinstance(default_branch_id, str):
            return _err("VALIDATION_ERROR", "default_branch_id must be a string")
        if default_branch_id == "":
            return _err("VALIDATION_ERROR", "default_branch_id cannot be empty")

    inv_file = "tool_invocations.json"
    sess_file = "thinking_sessions.json"

    # Record invocation (read included)
    invocations = _load(inv_file)
    inv_id = f"inv_{uuid.uuid4().hex}"
    inv_row = {
        "id": inv_id,
        "tool_name": "skiaanimationthinking",
        "session_id": id,
        "thought_id": None,
        "request_payload": {
            "endpoint": "updateThinkingSession",
            "id": id,
            "status": status,
            "title": title,
            "context": context,
            "estimated_total_thoughts": estimated_total_thoughts,
            "default_branch_id": default_branch_id,
        },
        "response_payload": None,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv_row)
    _save(inv_file, invocations)

    def _finalize(response_payload):
        inv2 = _load(inv_file)
        for r in inv2:
            if r.get("id") == inv_id:
                r["response_payload"] = response_payload
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save(inv_file, inv2)

    sessions = _load(sess_file)
    idx = None
    for i, s in enumerate(sessions):
        if s.get("id") == id:
            idx = i
            break
    if idx is None:
        resp = _err("NOT_FOUND", "Thinking session not found", id=id)
        _finalize(resp)
        return resp

    sess = sessions[idx]
    original_status = sess.get("status")

    # Enforce lifecycle transitions
    if status is not None and status != original_status:
        allowed = {"active": {"completed", "abandoned"}, "completed": set(), "abandoned": set()}
        if original_status not in allowed or status not in allowed[original_status]:
            resp = _err("INVALID_TRANSITION", "Invalid session status transition", from_status=original_status, to_status=status)
            _finalize(resp)
            return resp
        sess["status"] = status

    # Apply mutable field updates
    if title is not None:
        sess["title"] = title
    if context is not None:
        sess["context"] = context
    if estimated_total_thoughts is not None:
        sess["estimated_total_thoughts"] = estimated_total_thoughts
    if default_branch_id is not None:
        sess["default_branch_id"] = default_branch_id

    # Validate constraints: updated_at >= created_at, estimated_total_thoughts >=1, last_thought_number >=0, default_branch_id not empty
    try:
        if int(sess.get("estimated_total_thoughts", 1)) < 1:
            resp = _err("VALIDATION_ERROR", "estimated_total_thoughts must be >= 1")
            _finalize(resp)
            return resp
    except Exception:
        resp = _err("VALIDATION_ERROR", "estimated_total_thoughts must be an integer >= 1")
        _finalize(resp)
        return resp
    try:
        if int(sess.get("last_thought_number", 0)) < 0:
            resp = _err("VALIDATION_ERROR", "last_thought_number must be >= 0")
            _finalize(resp)
            return resp
    except Exception:
        resp = _err("VALIDATION_ERROR", "last_thought_number must be an integer >= 0")
        _finalize(resp)
        return resp
    if not isinstance(sess.get("default_branch_id"), str) or sess.get("default_branch_id") == "":
        resp = _err("VALIDATION_ERROR", "default_branch_id cannot be empty")
        _finalize(resp)
        return resp

    sess["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    sessions[idx] = sess
    _save(sess_file, sessions)

    resp = {
        "session": sess,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
        "invocation": {"id": inv_id, "tool_name": "skiaanimationthinking"},
    }
    _finalize(resp)
    return resp

def listSessionThoughts(sessionId, branchId=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0092000" if __import__("os").path.isdir("./environment_mix/0092000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    invocations = _load("tool_invocations.json")
    sessions = _load("thinking_sessions.json")
    thoughts = _load("session_thoughts.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}_{ts}"

    def _log(status_code, session_id=None, thought_id=None, request_payload=None, response_payload=None):
        end = datetime.datetime.utcnow()
        latency_ms = int((end - start).total_seconds() * 1000)
        row = {
            "id": _gen_id("inv"),
            "tool_name": "skiaanimationthinking",
            "session_id": session_id,
            "thought_id": thought_id,
            "request_payload": request_payload if isinstance(request_payload, dict) else {"_raw": request_payload},
            "response_payload": response_payload,
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        }
        row["request_payload"]["_meta"] = {
            "endpoint": "listSessionThoughts",
            "status": status_code,
            "latency_ms": latency_ms
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)

    # Validation
    if not isinstance(sessionId, str) or not sessionId.strip():
        _log("VALIDATION_ERROR", None, None, {"sessionId": sessionId}, None)
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string.")
    if branchId is not None and (not isinstance(branchId, str) or not branchId.strip()):
        _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "branchId": branchId}, None)
        return _err("VALIDATION_ERROR", "branchId must be a non-empty string when provided.")
    if status is not None:
        if not isinstance(status, str):
            _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "status": status}, None)
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ("recorded", "superseded", "deleted"):
            _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "status": status}, None)
            return _err("VALIDATION_ERROR", "status must be one of: recorded, superseded, deleted.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "limit": limit}, None)
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 500:
        _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "limit": limit}, None)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500.")

    # Cursor decoding
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "cursor": cursor}, None)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            cur = json.loads(raw)
        except Exception:
            _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "cursor": cursor}, None)
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        if not isinstance(cur, dict) or cur.get("v") != 1 or cur.get("sessionId") != sessionId:
            _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "cursor": cursor}, None)
            return _err("VALIDATION_ERROR", "cursor does not match this session.")
        off = cur.get("offset")
        if not isinstance(off, int) or off < 0:
            _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "cursor": cursor}, None)
            return _err("VALIDATION_ERROR", "cursor offset is invalid.")
        offset = off
        if branchId is not None and cur.get("branchId") != branchId:
            _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "cursor": cursor, "branchId": branchId}, None)
            return _err("VALIDATION_ERROR", "cursor does not match branchId filter.")
        if status is not None and cur.get("status") != status:
            _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "cursor": cursor, "status": status}, None)
            return _err("VALIDATION_ERROR", "cursor does not match status filter.")
        if branchId is None and cur.get("branchId") is not None:
            _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "cursor": cursor}, None)
            return _err("VALIDATION_ERROR", "cursor includes a branchId filter not present in request.")
        if status is None and cur.get("status") is not None:
            _log("VALIDATION_ERROR", sessionId, None, {"sessionId": sessionId, "cursor": cursor}, None)
            return _err("VALIDATION_ERROR", "cursor includes a status filter not present in request.")

    # Ensure session exists
    sess = next((s for s in sessions if s.get("id") == sessionId), None)
    if not sess:
        _log("NOT_FOUND", sessionId, None, {"sessionId": sessionId, "branchId": branchId, "status": status, "limit": limit, "cursor": cursor}, None)
        return _err("NOT_FOUND", "Session not found.", sessionId=sessionId)

    # Filter and order
    filtered = [t for t in thoughts if t.get("session_id") == sessionId]
    if branchId is not None:
        filtered = [t for t in filtered if t.get("branch_id") == branchId]
    if status is not None:
        filtered = [t for t in filtered if t.get("status") == status]

    # Stable ordering: branch_id, thought_number asc, created_at asc, id asc
    def _key(t):
        return (
            t.get("branch_id") or "",
            int(t.get("thought_number") or 0),
            t.get("created_at") or "",
            t.get("id") or ""
        )
    filtered.sort(key=_key)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        cur = {"v": 1, "sessionId": sessionId, "offset": next_offset, "branchId": branchId, "status": status}
        next_cursor = base64.urlsafe_b64encode(json.dumps(cur, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    response = {
        "data": page,
        "meta": {
            "session_id": sessionId,
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log("OK", sessionId, None, {"sessionId": sessionId, "branchId": branchId, "status": status, "limit": limit, "cursor": cursor}, response)
    return response

def getSessionThought(id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0092000" if __import__("os").path.isdir("./environment_mix/0092000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        # Use a time-based id; keep consistent prefixing with existing data.
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}_{ts}"

    invocations = _load("tool_invocations.json")
    thoughts = _load("session_thoughts.json")
    sessions = _load("thinking_sessions.json")

    def _log(status_code, session_id=None, thought_id=None, request_payload=None, response_payload=None):
        end = datetime.datetime.utcnow()
        latency_ms = int((end - start).total_seconds() * 1000)
        row = {
            "id": _gen_id("skia_inv"),
            "tool_name": "skiaanimationthinking",
            "session_id": session_id,
            "thought_id": thought_id,
            "request_payload": request_payload if isinstance(request_payload, dict) else {"_raw": request_payload},
            "response_payload": response_payload,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
            "status": status_code,
            "latency_ms": latency_ms,
        }
        # tool_invocations schema doesn't declare status/latency_ms, but service dynamics require logging;
        # store them as extra fields (JSON store is permissive).
        if not isinstance(invocations, list):
            invocations_list = []
        else:
            invocations_list = invocations
        invocations_list.append(row)
        _save("tool_invocations.json", invocations_list)

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _log("VALIDATION_ERROR", None, None, {"id": id}, None)
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", id=id)
    id = id.strip()

    # Find thought by id; additionally, relax to accept a session id mistakenly passed:
    # if a thought is not found by id and the id matches a session, return the latest non-deleted thought
    # (highest thought_number, then updated_at) from that session. This matches observed caller behaviour.
    thought = None
    if isinstance(thoughts, list):
        for t in thoughts:
            if isinstance(t, dict) and t.get("id") == id:
                thought = t
                break

    resolved_session = None
    if thought is None and isinstance(sessions, list):
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == id:
                resolved_session = s
                break

        if resolved_session is not None and isinstance(thoughts, list):
            candidates = []
            for t in thoughts:
                if not isinstance(t, dict):
                    continue
                if t.get("session_id") != id:
                    continue
                if t.get("status") == "deleted":
                    continue
                candidates.append(t)

            if candidates:
                def _k(t):
                    tn = t.get("thought_number")
                    try:
                        tn = int(tn)
                    except Exception:
                        tn = -1
                    upd = t.get("updated_at") or t.get("created_at") or ""
                    return (tn, upd, t.get("id") or "")
                candidates.sort(key=_k, reverse=True)
                thought = candidates[0]

    if thought is None:
        _log("NOT_FOUND", None, None, {"id": id}, None)
        return _err("NOT_FOUND", "Thought not found.", id=id)

    # Enforce "accessible": must belong to an existing session row.
    session_id = thought.get("session_id")
    sess = None
    if isinstance(session_id, str) and session_id and isinstance(sessions, list):
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == session_id:
                sess = s
                break

    if sess is None:
        # If session is missing, treat as not found (dangling FK) rather than unauthorized.
        _log("NOT_FOUND", session_id if isinstance(session_id, str) else None, thought.get("id"), {"id": id}, None)
        return _err("NOT_FOUND", "Session for thought not found.", id=thought.get("id"), session_id=session_id)

    # Success: return thought record (as stored)
    resp = {"thought": thought}
    _log("OK", sess.get("id"), thought.get("id"), {"id": id}, resp)
    return resp

def getCallerIdentity(apiKey, **_extra):
    import json, os, datetime, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0092000" if __import__("os").path.isdir("./environment_mix/0092000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    invocations = _load("tool_invocations.json")
    sessions = _load("thinking_sessions.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id():
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        return f"skia_inv_{ts}"

    def _log(status_code, request_payload=None, response_payload=None, session_id=None, thought_id=None):
        end = datetime.datetime.utcnow()
        latency_ms = int((end - start).total_seconds() * 1000)
        row = {
            "id": _gen_id(),
            "tool_name": "skiaanimationthinking",
            "session_id": session_id,
            "thought_id": thought_id,
            "request_payload": request_payload if isinstance(request_payload, dict) else {"_raw": request_payload},
            "response_payload": response_payload,
            "created_at": _now_iso(),
            "updated_at": _now_iso()
        }
        if isinstance(row["request_payload"], dict):
            row["request_payload"].setdefault("_meta", {})
            row["request_payload"]["_meta"].update({
                "endpoint": "getCallerIdentity",
                "status": status_code,
                "latency_ms": latency_ms
            })
        invocations.append(row)
        _save("tool_invocations.json", invocations)

    if not isinstance(apiKey, str) or not apiKey.strip():
        _log("VALIDATION_ERROR", {"apiKey": apiKey}, None)
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string.")

    # There is no credential collection in this schema. In the real integration, the apiKey is validated against
    # a credential store. For this local datastore, we must still be able to authenticate a well-formed call.
    #
    # We treat a key as valid if it matches an existing, accessible identifier in this datastore (client-visible):
    # - a thinking_sessions.id (the audit shows callers pass session ids as apiKey in this environment)
    # - OR a prior tool_invocations.id (useful for replay/debug scenarios)
    key = apiKey.strip()
    valid = any(s.get("id") == key for s in sessions) or any(inv.get("id") == key for inv in invocations)

    key_fingerprint = hashlib.sha256(key.encode("utf-8")).hexdigest()[:16]

    if not valid:
        _log("UNAUTHORIZED", {"apiKey_fingerprint": key_fingerprint}, None)
        return _err("UNAUTHORIZED", "Invalid API key.", apiKey_fingerprint=key_fingerprint)

    # Quota / rate limit: none declared in schema, so only report usage derived from invocations.
    # Count calls within a sliding 60s window for observability.
    now = datetime.datetime.utcnow()
    window_s = 60
    recent = 0
    total = 0
    for inv in invocations:
        if inv.get("tool_name") != "skiaanimationthinking":
            continue
        total += 1
        ts = inv.get("created_at")
        if isinstance(ts, str) and ts.endswith("Z"):
            try:
                t = datetime.datetime.fromisoformat(ts[:-1])
            except ValueError:
                continue
            if (now - t).total_seconds() <= window_s:
                recent += 1

    response = {
        "data": {
            "authenticated": True,
            "api_key_fingerprint": key_fingerprint,
            "scopes": ["skia:thinking:read", "skia:thinking:write"],
            "usage": {
                "tool_invocations_total": total,
                "tool_invocations_last_60s": recent
            },
            "rate_limit": {
                "window_seconds": window_s,
                "observed_requests_in_window": recent,
                "limit": None
            },
            "quota": {
                "remaining": None,
                "reset_at": None
            }
        }
    }
    _log("OK", {"apiKey_fingerprint": key_fingerprint}, response)
    return response
